style.css:
/* La Vie Parisienne — Global Paris 2000s */
 /* i really want this to be global */

/* change these colors whenever you want */
:root {
  --my-burgundy: #681d32;
  --my-wine: #873b50;
  --my-cream: #fff8ed;
  --my-white: #ffffff;
  --my-blush: #ead4d2;
  --my-ink: #492d34;
}

/* soft Parisian page background */
body {
  background-color: var(--my-cream) !important;
  color: var(--my-ink) !important;
  font-family: Georgia, "Times New Roman", serif !important;
}

/* romantic headings */
h1, h2, h3 {
  color: var(--my-burgundy) !important;
  font-family: Georgia, serif !important;
  letter-spacing: 1px !important;
}

/* burgundy links */
a {
  color: var(--my-burgundy) !important;
}

/* soft vintage buttons */
button {
  background: var(--my-burgundy) !important;
  color: var(--my-white) !important;
  border: 1px solid var(--my-blush) !important;
  border-radius: 18px !important;
}

/* delicate lace-inspired outlines */
img {
  border: 2px dotted var(--my-blush) !important;
  border-radius: 8px !important;
}

/* creamy content areas */
article, main, section {
  border-color: var(--my-blush) !important;
}
